<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое обеспечительный платёж?", "acceptedAnswer": {"@type": "Answer", "text": "Это денежная сумма, которую одна сторона договора вносит в пользу другой в обеспечение денежного обязательства, в том числе обязанности возместить убытки или уплатить неустойку (статья 381.1 Гражданского кодекса). При наступлении предусмотренных договором обстоятельств сумма засчитывается в счёт обязательства, а при их ненаступлении или прекращении обязательства — возвращается."}}, {"@type": "Question", "name": "Обеспечение исполнения контракта по 44-ФЗ — это обеспечительный платёж?", "acceptedAnswer": {"@type": "Answer", "text": "Когда обеспечение вносится деньгами на счёт заказчика (часть 3 статьи 96 Закона № 44-ФЗ), по правовой природе это обеспечительный платёж — так его квалифицируют суды. Второй способ обеспечения — независимая гарантия; у неё иная природа: это обязательство банка, а не депозит поставщика."}}, {"@type": "Question", "name": "Какой размер обеспечения исполнения контракта?", "acceptedAnswer": {"@type": "Answer", "text": "По общему правилу — от 0,5% до 30% начальной (максимальной) цены контракта (часть 6 статьи 96). Если предусмотрен аванс, обеспечение по общему правилу не может быть меньше размера аванса. При снижении цены на 25% и более обеспечение увеличивается в полтора раза (антидемпинговые меры, статья 37)."}}, {"@type": "Question", "name": "В какой срок возвращают обеспечение контракта?", "acceptedAnswer": {"@type": "Answer", "text": "Срок устанавливается контрактом и не может превышать 30 дней с даты исполнения поставщиком обязательств, а для закупок среди субъектов малого предпринимательства и социально ориентированных некоммерческих организаций — 15 дней (часть 27 статьи 34 Закона № 44-ФЗ)."}}, {"@type": "Question", "name": "Чем обеспечительный платёж отличается от задатка?", "acceptedAnswer": {"@type": "Answer", "text": "У задатка двусторонняя ответственность: виновная сторона либо теряет задаток, либо возвращает его в двойном размере (статьи 380–381 Гражданского кодекса). Обеспечительный платёж работает иначе — он либо засчитывается в счёт нарушенного обязательства, либо возвращается, без удвоения суммы."}}, {"@type": "Question", "name": "Можно ли внести обеспечение с лицевого счёта при казначейском сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Средства на лицевом счёте целевые и расходуются только на цели контракта через санкционирование, а перечисление обеспечения заказчику целевым расходом не является. Обеспечение вносят из собственных средств с расчётного счёта. Возврат обеспечения заказчик тоже перечисляет на расчётный счёт."}}, {"@type": "Question", "name": "Что выгоднее — внести деньги или независимую гарантию?", "acceptedAnswer": {"@type": "Answer", "text": "Зависит от ситуации. Денежное обеспечение замораживает ваши средства до возврата, зато не требует платы банку. Независимая гарантия сохраняет оборотный капитал, но стоит денег и требует одобрения банка. При сопровождении расчётов заказчик вправе вообще не требовать обеспечение или снизить его (часть 6.1 статьи 96)."}}, {"@type": "Question", "name": "Удерживают ли неустойку из обеспечения?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Если поставщик нарушил обязательства, начисленную неустойку заказчик вправе удержать из внесённого денежного обеспечения — в этом и состоит обеспечительная функция платежа. Возвращают тогда остаток. Порядок удержания и зачёта неустойки при сопровождении разобран в отдельной статье."}}, {"@type": "Question", "name": "Начисляются ли проценты на сумму обеспечительного платежа?", "acceptedAnswer": {"@type": "Answer", "text": "По общему правилу нет: на сумму обеспечительного платежа проценты по статье 317.1 Гражданского кодекса не начисляются, если иное не предусмотрено договором. То есть заказчик не платит поставщику за пользование внесёнными деньгами, если стороны не договорились об обратном."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как внести и вернуть денежное обеспечение исполнения контракта", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Выберите способ обеспечения", "text": "Определите, что выгоднее по контракту: внести денежное обеспечение (обеспечительный платёж) на счёт заказчика или предоставить независимую гарантию по статье 45 Закона № 44-ФЗ."}, {"@type": "HowToStep", "position": 2, "name": "Рассчитайте размер", "text": "Возьмите размер из извещения и контракта (от 0,5% до 30% начальной цены); при авансе — не менее аванса; при снижении цены на 25% и более учтите увеличение в полтора раза."}, {"@type": "HowToStep", "position": 3, "name": "Внесите обеспечение из собственных средств", "text": "Перечислите деньги на указанный заказчиком счёт со своего расчётного счёта; на сопровождаемом контракте не используйте для этого целевой лицевой счёт."}, {"@type": "HowToStep", "position": 4, "name": "Исполните контракт и подтвердите", "text": "Выполните обязательства, оформите приёмку; при удержании неустойки заказчик вычтет её из обеспечения."}, {"@type": "HowToStep", "position": 5, "name": "Сообщите реквизиты для возврата", "text": "Передайте заказчику актуальные банковские реквизиты расчётного счёта, на который нужно вернуть обеспечение."}, {"@type": "HowToStep", "position": 6, "name": "Получите возврат в срок", "text": "Дождитесь возврата в срок по контракту — не более 30 дней (15 дней для закупок среди малого бизнеса) с даты исполнения обязательств."}]}
</script>
